import Foundation
import Testing
@testable import Actualist

/// The Enable Banking server transport against Actual's own server output:
/// every response comes from `EnableBankingServer`, generated by running the
/// pinned sync-server routes on synthetic Enable Banking payloads
/// (`scripts/enablebanking-server-parity/`). Expected values are read from
/// the recorded server response, never written here; the only hand-written
/// answers are the loot-core status table and transport failures no Actual
/// code produces. The suite stays serialized; each test owns its endpoint.
@Suite(.serialized)
struct EnableBankingClientTests {
    private let endpoint = StubHTTPEndpoint()

    /// Every scenario, so a new one fails the partition test until it is replayed here.
    nonisolated static let downloadScenarios = [
        "booked-and-pending", "missing-ids", "date-fallbacks", "payee-and-sign", "non-eur-account",
        "zero-decimal-currency", "balances-without-clav", "balances-empty", "pagination", "empty-download",
        "no-aspsp-name", "pending-before-booking", "pending-after-booking",
    ]
    nonisolated static let errorScenarios = [
        "expired-session-unauthorized", "expired-session-closed", "expired-session-on-transactions",
        "rate-limited", "account-not-found", "wrong-period", "provider-error", "provider-timeout",
        "not-configured", "missing-start-date",
    ]
    nonisolated static let statusScenarios = ["status-configured", "status-not-configured"]
    nonisolated static let routeScenarios = ["routes-missing"]

    private func makeClient(_ scenario: EnableBankingServerFixture.Scenario, customHeaders: HTTPHeaderFields = .empty) -> ActualServerEnableBankingClient {
        endpoint.respond(statusCode: scenario.status, body: scenario.bodyText)
        return makeClient(configuration: endpoint.makeConfiguration(), customHeaders: customHeaders)
    }

    private func makeClient(configuration: URLSessionConfiguration, customHeaders: HTTPHeaderFields = .empty) -> ActualServerEnableBankingClient {
        ActualServerEnableBankingClient(
            baseURL: URL(string: "https://sync.example")!,
            customHeaders: customHeaders,
            session: URLSession(configuration: configuration)
        )
    }

    private func transactions(_ client: ActualServerEnableBankingClient, _ scenario: EnableBankingServerFixture.Scenario) async throws -> SimpleFINAccountDownload? {
        try await client.transactions(
            token: "synthetic-token",
            accountID: try OracleJSON.string(scenario.requestBody, "accountId"),
            startDate: try OracleJSON.string(scenario.requestBody, "startDate"),
            aspspName: scenario.requestBody["aspspName"] as? String
        )
    }

    // MARK: - Fixture

    @Test func fixtureMatchesThePinnedOracle() throws {
        let pin = try ParityOraclePin.load()
        let fixture = try EnableBankingServerFixture.load()
        let oracle = try OracleJSON.object(fixture.root["oracle"], "oracle")
        #expect(oracle["tag"] as? String == pin.tag)
        #expect(oracle["commit"] as? String == pin.commit)
        #expect(try OracleJSON.object(fixture.root["syntheticData"], "syntheticData")["only"] as? Bool == true)
    }

    @Test func everyScenarioIsReplayed() throws {
        let listed = Self.downloadScenarios + Self.errorScenarios + Self.statusScenarios + Self.routeScenarios
        #expect(Set(listed).count == listed.count)
        #expect(Set(listed) == Set(try EnableBankingServerFixture.load().ids))
    }

    // MARK: - Downloads

    /// The request a client sends is the request the oracle answered, minus nothing: the body
    /// keys, the token header, no file ID (credentials are server-wide) and Actual's 60 s timeout.
    @Test(arguments: downloadScenarios + errorScenarios.filter { $0 != "missing-start-date" })
    func sendsTheRequestTheServerAnswered(scenarioID: String) async throws {
        let scenario = try EnableBankingServerFixture.load().scenario(scenarioID)
        _ = try await transactions(makeClient(scenario), scenario)
        let request = try #require(endpoint.lastRequest)
        #expect(request.httpMethod == "POST")
        #expect(request.url?.path == "/enablebanking\(scenario.requestPath)")
        #expect(request.value(forHTTPHeaderField: "X-ACTUAL-TOKEN") == "synthetic-token")
        #expect(request.value(forHTTPHeaderField: "X-ACTUAL-FILE-ID") == nil)
        #expect(request.value(forHTTPHeaderField: "Content-Type") == "application/json")
        #expect(request.timeoutInterval == 60)
        let sent = try JSONSerialization.jsonObject(with: try #require(endpoint.lastRequestBody)) as? NSDictionary
        #expect(sent == scenario.requestBody as NSDictionary)
    }

    /// Each normalized row and the balance evidence decode to exactly what the server sent.
    @Test(arguments: downloadScenarios)
    func decodesTheServersDownload(scenarioID: String) async throws {
        let scenario = try EnableBankingServerFixture.load().scenario(scenarioID)
        let download = try #require(try await transactions(makeClient(scenario), scenario))
        let data = try OracleJSON.object(scenario.body["data"], "data")
        let rows = try OracleJSON.objects(OracleJSON.object(data["transactions"], "transactions")["all"], "all")

        #expect(download.errorCode == nil)
        #expect(download.errorType == nil)
        #expect(download.currentBalance == nil, "an Enable Banking balance is never a decimal string")
        #expect(download.startingBalance == nil)
        #expect(download.transactions.count == rows.count)
        for (transaction, row) in zip(download.transactions, rows) {
            let amount = try OracleJSON.object(row["transactionAmount"], "transactionAmount")
            #expect(transaction.id == row["transactionId"] as? String)
            #expect(transaction.dateUnixSeconds.map(BankSyncAmounts.dayID(fromUnixSeconds:))
                == (row["date"] as? String)?.replacingOccurrences(of: "-", with: ""))
            #expect(transaction.amount == amount["amount"] as? String)
            #expect(transaction.currency == amount["currency"] as? String)
            #expect(transaction.payeeName == row["payeeName"] as? String)
            #expect(transaction.notes == row["notes"] as? String)
            #expect(transaction.booked == row["booked"] as? Bool)
            #expect(Set(transaction.rawFields.values.keys) == Set(row.keys), "custom mappings see every field")
        }

        let balances = try OracleJSON.objects(data["balances"], "balances")
        if balances.isEmpty {
            #expect(download.minorUnitBalance == nil, "the server's 0 for no balance is not evidence")
        } else {
            let preferred = balances.first { $0["balanceType"] as? String == "CLAV" } ?? balances[0]
            let preferredAmount = try OracleJSON.object(preferred["balanceAmount"], "balanceAmount")
            #expect(download.minorUnitBalance == BankSyncMinorUnitBalance(
                amount: try #require(OracleJSON.int(data["startingBalance"])),
                currency: preferredAmount["currency"] as? String
            ))
            #expect(OracleJSON.int(preferredAmount["amount"]) == OracleJSON.int(data["startingBalance"]))
        }
    }

    // MARK: - Errors

    /// loot-core `getBankSyncStatusFromError` (`accounts/app.ts`) on the category and code each
    /// server error envelope carries.
    private static let lootCoreStatus: [String: ActualBankSyncDurableStatus] = [
        "expired-session-unauthorized": .reauthRequired,
        "expired-session-closed": .reauthRequired,
        "expired-session-on-transactions": .reauthRequired,
        "rate-limited": .rateLimitExceeded,
        "account-not-found": .failed,
        "wrong-period": .failed,
        "provider-error": .failed,
        "provider-timeout": .timedOut,
        "not-configured": .notConfigured,
        "missing-start-date": .failed,
    ]

    /// An HTTP 200 error envelope is that account's failed download, not a thrown error.
    @Test(arguments: errorScenarios)
    func providerFailureIsAPerAccountDownloadError(scenarioID: String) async throws {
        let scenario = try EnableBankingServerFixture.load().scenario(scenarioID)
        let data = try OracleJSON.object(scenario.body["data"], "data")
        let download = scenarioID == "missing-start-date"
            ? try ActualServerEnableBankingClient.decodeTransactionsResponse(from: Data(scenario.bodyText.utf8))
            : try #require(try await transactions(makeClient(scenario), scenario))
        #expect(download.errorCode == data["error_code"] as? String)
        #expect(download.errorType == data["error_type"] as? String)
        #expect(download.transactions.isEmpty)
        #expect(download.minorUnitBalance == nil)
        #expect(ActualBankSyncDurableStatus.from(errorCode: download.errorCode) == Self.lootCoreStatus[scenarioID])
    }

    @Test func echoedCredentialInAnErrorFailsClosed() async throws {
        let scenario = try EnableBankingServerFixture.load().scenario("not-configured")
        let headers = try HTTPHeaderFields(endpoint: EndpointCustomHTTPHeaders(
            url: URL(string: "https://sync.example")!, headers: [.init(name: "X-Proxy", value: "NOT_CONFIGURED")]
        ))
        await #expect(throws: ActualAPIError.self) {
            _ = try await transactions(makeClient(scenario, customHeaders: headers), scenario)
        }
    }

    // MARK: - Status and unsupported servers

    @Test(arguments: statusScenarios)
    func statusReadsTheServersAnswer(scenarioID: String) async throws {
        let scenario = try EnableBankingServerFixture.load().scenario(scenarioID)
        let configured = try OracleJSON.object(scenario.body["data"], "data")["configured"] as? Bool
        let support = try await makeClient(scenario).status(token: "synthetic-token")
        #expect(support == (configured == true ? .configured : .notConfigured))
        #expect(endpoint.lastRequest?.url?.path == "/enablebanking/status")
        #expect(endpoint.lastRequest?.value(forHTTPHeaderField: "X-ACTUAL-FILE-ID") == nil)
    }

    @Test func serverWithoutTheRoutesCannotSyncRatherThanFailing() async throws {
        let scenario = try EnableBankingServerFixture.load().scenario("routes-missing")
        #expect(scenario.status == 404)
        #expect(try await transactions(makeClient(scenario), scenario) == nil)
        #expect(try await makeClient(scenario).status(token: "synthetic-token") == .unsupported)
    }

    // MARK: - Transport failures (no Actual code produces these)

    @Test func nonJSONGatewayErrorThrowsTheHTTPStatus() async throws {
        endpoint.respond(statusCode: 502, body: "<html>Bad gateway</html>")
        let client = makeClient(configuration: endpoint.makeConfiguration())
        do {
            _ = try await client.transactions(token: "synthetic-token", accountID: "eb-acct", startDate: "2026-07-18", aspspName: nil)
            Issue.record("expected a thrown HTTP status")
        } catch ActualAPIError.httpStatus(let status) {
            #expect(status == 502)
        }
    }

    @Test func successWithoutTransactionsIsADecodingError() async throws {
        endpoint.respond(statusCode: 200, body: #"{"status":"ok","data":{"balances":[],"startingBalance":0}}"#)
        let client = makeClient(configuration: endpoint.makeConfiguration())
        do {
            _ = try await client.transactions(token: "synthetic-token", accountID: "eb-acct", startDate: "2026-07-18", aspspName: nil)
            Issue.record("expected a decoding error")
        } catch ActualAPIError.decoding {}
    }

    @Test func clientTimeoutIsATimedOutTransportError() async throws {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.protocolClasses = [TimedOutEnableBankingURLProtocol.self]
        let client = makeClient(configuration: configuration)
        do {
            _ = try await client.transactions(token: "synthetic-token", accountID: "eb-acct", startDate: "2026-07-18", aspspName: nil)
            Issue.record("expected a timeout")
        } catch ActualAPIError.transport(let code) {
            #expect(code == .timedOut)
        }
    }
}

/// The `EnableBankingServer` oracle fixture (see `scripts/enablebanking-server-parity/README.md`).
struct EnableBankingServerFixture {
    static let fileName = "enablebanking-server-contract.json"

    struct Scenario {
        let id: String
        let requestPath: String
        let requestBody: [String: Any]
        let status: Int
        let bodyText: String
        /// The parsed JSON body; empty for a non-JSON answer.
        let body: [String: Any]
    }

    let root: [String: Any]
    private let scenarios: [String: Scenario]
    var ids: [String] { Array(scenarios.keys) }

    static func load() throws -> EnableBankingServerFixture {
        let url = try ParityOraclePin.fixtureURL("EnableBankingServer").appending(path: fileName)
        guard FileManager.default.fileExists(atPath: url.path) else { throw OracleReplayError.missingFixture(url.path) }
        let root = try OracleJSON.object(OracleJSONFileCache.jsonObject(at: url), fileName)
        var byID: [String: Scenario] = [:]
        for record in try OracleJSON.objects(root["scenarios"], "scenarios") {
            let id = try OracleJSON.string(record, "id")
            let request = try OracleJSON.object(record["request"], "request")
            let response = try OracleJSON.object(record["response"], "response")
            guard byID[id] == nil, let status = OracleJSON.int(response["status"]) else {
                throw OracleReplayError.malformedFixture("scenario \(id)")
            }
            byID[id] = Scenario(
                id: id,
                requestPath: try OracleJSON.string(request, "path"),
                requestBody: try OracleJSON.object(request["body"], "request.body"),
                status: status,
                bodyText: try OracleJSON.string(response, "bodyText"),
                body: (response["body"] as? [String: Any]) ?? [:]
            )
        }
        return EnableBankingServerFixture(root: root, scenarios: byID)
    }

    func scenario(_ id: String) throws -> Scenario {
        guard let scenario = scenarios[id] else { throw OracleReplayError.unknownCase(id) }
        return scenario
    }
}

private final class TimedOutEnableBankingURLProtocol: URLProtocol {
    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }
    override func startLoading() {
        client?.urlProtocol(self, didFailWithError: URLError(.timedOut))
    }
    override func stopLoading() {}
}
